INSERT INTO normative_docs (code, content, id, keywords, section, title) VALUES ('СН РК 1.02-01-2011', 'Проект организации строительства (ПОС) входит в состав проектной документации и включает календарный план строительства, ведомость объёмов работ, график потребности в материально-технических ресурсах. Стоимость строительства определяется сводным сметным расчётом. Для объектов производственного назначения дополнительно разрабатывается проект производства работ (ППР).', 'a7f50ee8-cd62-4c7d-9e4a-13dfb7ce5c42', 'пос строительство организация календарный план этапы', 'Раздел 4. Состав ПОС', 'Инструкция по разработке проектов организации строительства');
INSERT INTO normative_docs (code, content, id, keywords, section, title) VALUES ('СП РК 3.02-101-2012', 'Несущие конструктивные элементы жилых зданий должны обеспечивать прочность, жёсткость и устойчивость при восприятии расчётных нагрузок. Монолитный железобетонный каркас допускается проектировать с классом бетона не ниже B25 по прочности. Армирование выполняется с учётом требований по минимальному проценту армирования.', 'ecc2b1a0-daba-4953-98e8-d3b992bbeebd', 'жилые здания несущие конструкции монолит каркас', 'Раздел 5. Конструктивные решения', 'Жилые здания. Общие положения');
INSERT INTO normative_docs (code, content, id, keywords, section, title) VALUES ('ГОСТ 21.501-2018', 'На схемах расположения элементов конструкций указывают арматурные изделия, класс бетона, защитный слой бетона. Ведомости и спецификации элементов оформляются в соответствии с требованиями к оформлению рабочей документации. Характеристики материалов приводят в ведомости расхода материалов.', 'deaca8e4-d0f2-462c-9d1f-765d67faee89', 'чертежи схемы рабочая документация армирование', 'Раздел 6. Схемы', 'Правила выполнения рабочей документации архитектурных и конструктивных решений');
INSERT INTO normative_docs (code, content, id, keywords, section, title) VALUES ('СП РК 4.01-102-2012', 'Трубопроводы систем водоснабжения перед вводом в эксплуатацию подвергаются гидравлическим испытаниям на прочность и герметичность. Испытательное давление принимается не менее 1,25 рабочего, но не менее 0,3 МПа для систем хозяйственно-питьевого водоснабжения.', '4abc3247-a4a8-485f-8dd2-118981d22cd9', 'водоснабжение трубопровод сети монтаж испытания', 'Раздел 8. Трубопроводы', 'Водоснабжение. Наружные сети и сооружения');
INSERT INTO normative_docs (code, content, id, keywords, section, title) VALUES ('СТ РК 1.02-2018', 'Приёмка выполненных работ оформляется актом по форме КС-2 (акт о приёмке выполненных работ) и справкой по форме КС-3 (справка о стоимости выполненных работ и затрат). Ведомость выполненных работ составляется по позициям сметы с указанием объёмов и стоимости. Заказчик проверяет соответствие объёмов проектной документации и при отсутствии замечаний подписывает документы.', 'a54ccded-83f0-4b97-89e9-395b6c63ba1f', 'кс-2 кс-3 акт приёмка исполнительная документация формы', 'Раздел 3. Исполнительная документация', 'Порядок проведения приёмки выполненных строительно-монтажных работ');
INSERT INTO normative_docs (code, content, id, keywords, section, title) VALUES ('СН РК 4.01-03-2011', 'Перед устройством фундаментов выполняется геодезическая разбивка и подготовка основания. При разработке котлована в зимних условиях необходимо обеспечивать защиту основания от промерзания. Обратная засыпка выполняется послойным уплотнением до проектной плотности.', '41ce2500-a31d-4f60-ba47-b35696a516d5', 'фундамент земляные работы котлован основание', 'Раздел 5. Земляные работы', 'Инженерные сети. Основания и фундаменты');
INSERT INTO normative_docs (code, content, id, keywords, section, title) VALUES ('СП РК 2.03-101-2012', 'Кровельные покрытия должны обеспечивать отвод атмосферных осадков и защиту конструкций от увлажнения. Для гидроизоляции применяются рулонные битумно-полимерные материалы с защитным слоем. На эксплуатируемых кровлях устраивается разуклонка к водоприёмным воронкам.', 'caea30e1-0d0c-4018-94b9-447298fe9128', 'кровля гидроизоляция материалы покрытие', 'Раздел 6. Устройство кровли', 'Крыши и кровли. Общие требования');
INSERT INTO normative_docs (code, content, id, keywords, section, title) VALUES ('СТ РК 1.02-2009', 'Исполнительная геодезическая съёмка выполняется после завершения возведения конструкций и фиксирует фактические отклонения от проектных отметок. Допуски на монтаж конструкций устанавливаются проектом. Результаты съёмки прилагаются к актам освидетельствования скрытых работ.', '06a8a621-95e7-4839-8bb4-08d24e3e7900', 'геодезия разбивка исполнительная съёмка допуски', 'Раздел 2. Контроль точности', 'Инженерно-геодезические работы в строительстве');
